import itertools
import json

# Exhaustive finite check: each option is encoded as (premise, conclusion) over
# two predicates P and Q, each a tuple of booleans across a finite universe.
def exists(seq):
    return any(seq)

def counterexample(prem, concl, max_n=3):
    # Search universes of size 1..max_n for a model where premise holds and conclusion fails.
    for n in range(1, max_n + 1):
        for P in itertools.product([False, True], repeat=n):
            for Q in itertools.product([False, True], repeat=n):
                if prem(P, Q) and not concl(P, Q):
                    return {"universe_size": n, "P": list(map(int, P)), "Q": list(map(int, Q))}
    return None

# Original argument: Some good are not cheap; therefore some cheap are not good.
# P = good, Q = cheap. Premise: exists P and not Q. Conclusion: exists Q and not P.
orig_prem = lambda P, Q: exists(p and not q for p, q in zip(P, Q))
orig_concl = lambda P, Q: exists(q and not p for p, q in zip(P, Q))

options = {
    # A: some Hunan people don't like pepper -> some pepper-lovers aren't from Hunan
    "A": (orig_prem, orig_concl),
    # B: some people are not selfish -> people are not all selfish
    "B": (lambda P, Q: exists(not p for p in P),
          lambda P, Q: not all(P)),
    # C: some good motives lack good effects -> some good results don't come from good motives
    "C": (orig_prem, orig_concl),
    # D: some southerners aren't Cantonese -> some Cantonese aren't southerners
    "D": (orig_prem, orig_concl),
}

# The original form is invalid; check the original and each option.
orig_cex = counterexample(orig_prem, orig_concl)

results = {}
for label, (prem, concl) in options.items():
    cex = counterexample(prem, concl)
    results[label] = {"valid": cex is None, "counterexample": cex}

# The option that does not share the invalid pattern of the original conclusion.
differing = [label for label, r in results.items() if r["valid"]]
final_answer = differing[0] if len(differing) == 1 else "UNSUPPORTED"

print(json.dumps({
    "final_answer": final_answer,
    "evidence": {
        "original_counterexample": orig_cex,
        "options": results,
    }
}, separators=(",", ":")))
